import{_ as e,o as l,c as i,O as t}from"./chunks/framework.db831a78.js";const k=JSON.parse('{"title":"中间件（Redis / MQ）","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/06-中间件.md","filePath":"interview/后端/Java/06-中间件.md","lastUpdated":null}'),r={name:"interview/后端/Java/06-中间件.md"};function o(s,a,d,h,n,u){return l(),i("div",null,a[0]||(a[0]=[t('<h1 id="中间件-redis-mq" tabindex="-1">中间件（Redis / MQ） <a class="header-anchor" href="#中间件-redis-mq" aria-label="Permalink to &quot;中间件（Redis / MQ）&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h2><h3 id="常用数据结构及使用场景-★★★" tabindex="-1">常用数据结构及使用场景 ★★★ <a class="header-anchor" href="#常用数据结构及使用场景-★★★" aria-label="Permalink to &quot;常用数据结构及使用场景 ★★★&quot;">​</a></h3><ul><li>String：缓存、计数、分布式锁、session；Hash：对象属性存储（购物车）；List：消息队列、时间线；Set：去重、交并差（共同关注）；ZSet：排行榜（带 score）；Bitmap/HyperLogLog/GEO（补充）。</li></ul><h3 id="rdb-与-aof-持久化对比-★★★" tabindex="-1">RDB 与 AOF 持久化对比 ★★★ <a class="header-anchor" href="#rdb-与-aof-持久化对比-★★★" aria-label="Permalink to &quot;RDB 与 AOF 持久化对比 ★★★&quot;">​</a></h3><ul><li>RDB：指定时间/次数生成快照二进制文件，恢复快、体积小，但最后一次持久化后数据可能丢；fork 子进程。</li><li>AOF：追加写命令日志，更可靠（可配置每次/每秒刷盘），文件大、恢复较慢；AOF 重写压缩。</li><li>通常二者结合；Redis 4.0 起支持混合持久化（RDB 前缀 + AOF 增量）。</li></ul><h3 id="redis-过期淘汰策略-★★★" tabindex="-1">Redis 过期淘汰策略 ★★★ <a class="header-anchor" href="#redis-过期淘汰策略-★★★" aria-label="Permalink to &quot;Redis 过期淘汰策略 ★★★&quot;">​</a></h3><ul><li>过期删除：惰性删除 + 定期删除（混合）。</li><li>内存淘汰：noeviction（默认报错）、allkeys-lru/lfu、volatile-lru/lfu、volatile-random、allkeys-random、volatile-ttl。</li></ul><h3 id="缓存穿透、缓存击穿、缓存雪崩-★★★" tabindex="-1">缓存穿透、缓存击穿、缓存雪崩 ★★★ <a class="header-anchor" href="#缓存穿透、缓存击穿、缓存雪崩-★★★" aria-label="Permalink to &quot;缓存穿透、缓存击穿、缓存雪崩 ★★★&quot;">​</a></h3><ul><li>穿透：查一个根本不存在的 key，绕过缓存直打到 DB。解决：缓存空值、布隆过滤器、参数校验。</li><li>击穿：热点 key 过期瞬间大量请求打到 DB。解决：热点不过期、互斥锁重建、逻辑过期。</li><li>雪崩：大量 key 同时过期或 Redis 挂掉。解决：过期时间加随机、集群高可用、多级缓存、限流降级。</li></ul><h3 id="redis-分布式锁实现-存在什么问题-★★★" tabindex="-1">Redis 分布式锁实现；存在什么问题 ★★★ <a class="header-anchor" href="#redis-分布式锁实现-存在什么问题-★★★" aria-label="Permalink to &quot;Redis 分布式锁实现；存在什么问题 ★★★&quot;">​</a></h3><ul><li>实现：<code>SET key value NX PX ttl</code>（原子占锁）+ random value，释放时 Lua 脚本校验 value 再 del（防误删）。</li><li>问题：锁过期任务未完成（看门狗续期/Redisson）、主从切换锁丢失（RedLock/集群）、集群脑裂。Redisson 提供可重入、自动续期。</li></ul><h3 id="redis-哨兵、集群模式-★★★" tabindex="-1">Redis 哨兵、集群模式 ★★★ <a class="header-anchor" href="#redis-哨兵、集群模式-★★★" aria-label="Permalink to &quot;Redis 哨兵、集群模式 ★★★&quot;">​</a></h3><ul><li>哨兵（Sentinel）：监控主从、故障自动转移（选新主），解决高可用但不解决扩容。</li><li>集群（Cluster）：16384 个 slot 分片，多主多从，数据分散、横向扩容，客户端按 slot 路由；不支持跨 slot 的多 key 原子操作（可用 hash tag）。</li></ul><h3 id="底层数据结构-sds、跳表、listpack-等-★★☆" tabindex="-1">底层数据结构（SDS、跳表、listpack 等）★★☆ <a class="header-anchor" href="#底层数据结构-sds、跳表、listpack-等-★★☆" aria-label="Permalink to &quot;底层数据结构（SDS、跳表、listpack 等）★★☆&quot;">​</a></h3><ul><li>SDS 动态字符串（len/alloc 记录，二进制安全）；List 用 quicklist（链表 + listpack）；ZSet 用跳表 + 字典；Set 用 hashtable 或 intset；Hash 用 listpack 或 hashtable。压缩列表已逐步被 listpack 替代。</li></ul><h3 id="为什么-redis-快-★★★" tabindex="-1">为什么 Redis 快 ★★★ <a class="header-anchor" href="#为什么-redis-快-★★★" aria-label="Permalink to &quot;为什么 Redis 快 ★★★&quot;">​</a></h3><ul><li>纯内存操作；单线程避免锁与上下文切换（核心命令单线程）；IO 多路复用（epoll）处理大量连接；高效数据结构。</li></ul><h3 id="大-key、热-key-★★☆" tabindex="-1">大 key、热 key ★★☆ <a class="header-anchor" href="#大-key、热-key-★★☆" aria-label="Permalink to &quot;大 key、热 key ★★☆&quot;">​</a></h3><ul><li>大 key：单 key 过大（string 大 value、集合元素多）导致阻塞、网络抖动、迁移慢；需拆分、压缩、提前规避。</li><li>热 key：访问集中在少数 key，导致单节点瓶颈；可本地缓存、多个副本、拆分 key。</li></ul><h3 id="缓存一致性-延迟双删、canal-★★★" tabindex="-1">缓存一致性（延迟双删、Canal）★★★ <a class="header-anchor" href="#缓存一致性-延迟双删、canal-★★★" aria-label="Permalink to &quot;缓存一致性（延迟双删、Canal）★★★&quot;">​</a></h3><ul><li>常用：先更新 DB 再删缓存；延迟双删（更新前后各删一次，第二次延迟）；Canal 订阅 binlog 异步删缓存，实现最终一致。</li></ul><h3 id="布隆过滤器、bitmap-hyperloglog-geo-★★☆" tabindex="-1">布隆过滤器、Bitmap/HyperLogLog/GEO ★★☆ <a class="header-anchor" href="#布隆过滤器、bitmap-hyperloglog-geo-★★☆" aria-label="Permalink to &quot;布隆过滤器、Bitmap/HyperLogLog/GEO ★★☆&quot;">​</a></h3><ul><li>布隆过滤器：概率型判重，不存在一定对、存在可能误判，解决穿透；Bitmap 位图统计（签到）；HyperLogLog 近似去重计数；GEO 地理位置。</li></ul><h3 id="redis-6-0-多线程-★★☆" tabindex="-1">Redis 6.0 多线程 ★★☆ <a class="header-anchor" href="#redis-6-0-多线程-★★☆" aria-label="Permalink to &quot;Redis 6.0 多线程 ★★☆&quot;">​</a></h3><ul><li>多线程只用于网络 IO 读写（socket）、命令执行仍单线程；解决网络 IO 瓶颈，保证命令原子性不受影响。</li></ul><h2 id="mq-rabbitmq-kafka-rocketmq" tabindex="-1">MQ（RabbitMQ / Kafka / RocketMQ） <a class="header-anchor" href="#mq-rabbitmq-kafka-rocketmq" aria-label="Permalink to &quot;MQ（RabbitMQ / Kafka / RocketMQ）&quot;">​</a></h2><h3 id="使用消息队列的好处-使用场景-★★★" tabindex="-1">使用消息队列的好处；使用场景 ★★★ <a class="header-anchor" href="#使用消息队列的好处-使用场景-★★★" aria-label="Permalink to &quot;使用消息队列的好处；使用场景 ★★★&quot;">​</a></h3><ul><li>好处：异步（提升响应）、削峰填谷（平滑流量）、解耦（系统间松耦合）。</li><li>场景：订单异步处理、日志收集、秒杀流量削峰、系统解耦、最终一致性。</li></ul><h3 id="消息丢失、重复消费、积压处理-★★★" tabindex="-1">消息丢失、重复消费、积压处理 ★★★ <a class="header-anchor" href="#消息丢失、重复消费、积压处理-★★★" aria-label="Permalink to &quot;消息丢失、重复消费、积压处理 ★★★&quot;">​</a></h3><ul><li>丢失：生产者 confirm/事务、MQ 持久化（消息+队列）、消费者手动 ack（消费成功再确认）。</li><li>重复：消费端幂等（唯一 id 去重、数据库唯一约束、Redis set）；MQ 至少一次投递需配合幂等。</li><li>积压：扩容消费者、批量消费、临时提升消费速度、优先消费新消息/丢弃低价值消息。</li></ul><h3 id="rabbitmq-交换机类型-kafka-高可用-★★★" tabindex="-1">RabbitMQ 交换机类型；Kafka 高可用 ★★★ <a class="header-anchor" href="#rabbitmq-交换机类型-kafka-高可用-★★★" aria-label="Permalink to &quot;RabbitMQ 交换机类型；Kafka 高可用 ★★★&quot;">​</a></h3><ul><li>RabbitMQ 交换机：direct（精确路由键）、fanout（广播）、topic（通配符路由）、headers（头匹配）。</li><li>Kafka 高可用：副本机制（leader/follower，ISR），leader 故障选举新 leader；分区分散在多 broker 提升吞吐与容错。</li></ul><h3 id="各-mq-对比选型-★★☆" tabindex="-1">各 MQ 对比选型 ★★☆ <a class="header-anchor" href="#各-mq-对比选型-★★☆" aria-label="Permalink to &quot;各 MQ 对比选型 ★★☆&quot;">​</a></h3><ul><li>RabbitMQ：低延迟、成熟、功能丰富（延迟/死信/优先级），吞吐中等，适合业务解耦与事务性消息。</li><li>Kafka：超高吞吐、持久化、顺序、分区，适合日志/大数据流；不强调消息确认与重试灵活性。</li><li>RocketMQ：阿里系，兼顾高吞吐与事务消息、顺序消息、延迟消息，适合金融/电商。</li></ul><h3 id="顺序消息、事务消息、延迟消息、死信队列-★★☆" tabindex="-1">顺序消息、事务消息、延迟消息、死信队列 ★★☆ <a class="header-anchor" href="#顺序消息、事务消息、延迟消息、死信队列-★★☆" aria-label="Permalink to &quot;顺序消息、事务消息、延迟消息、死信队列 ★★☆&quot;">​</a></h3><ul><li>顺序：单分区/单 queue + 单消费者 + 同步发送保证有序（Kafka 同 key 同分区，RocketMQ 顺序队列）。</li><li>事务消息：RocketMQ 半消息 → 本地事务 → commit/rollback + 回查机制。</li><li>延迟消息：RabbitMQ TTL+死信、RocketMQ 延迟等级、Kafka 手动定时。</li><li>死信队列：消费失败重试超限后进入死信，便于人工处理。</li></ul>',38)]))}const b=e(r,[["render",o]]);export{k as __pageData,b as default};
